<?php
require_once __DIR__.'/config/app.php';require_login();$uid=(int)$_SESSION['user_id'];$id=(int)($_GET['id']??0);$message='';$s=mysqli_prepare($conn,'SELECT items.*,users.full_name FROM items INNER JOIN users ON users.id=items.user_id WHERE items.id=?');mysqli_stmt_bind_param($s,'i',$id);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);if(mysqli_num_rows($r)!==1){header('Location: search-items.php');exit();}$item=mysqli_fetch_assoc($r);if($item['type']!=='found'||$item['status']!=='active'||(int)$item['user_id']===$uid){set_flash('error','This item cannot be claimed.');header('Location: search-items.php');exit();}if($_SERVER['REQUEST_METHOD']==='POST'){$msg=trim($_POST['message']??'');if($msg==='')$message='Please explain why you believe this item belongs to you.';else{$c=mysqli_prepare($conn,"SELECT id FROM claims WHERE item_id=? AND user_id=? AND status='pending'");mysqli_stmt_bind_param($c,'ii',$id,$uid);mysqli_stmt_execute($c);if(mysqli_num_rows(mysqli_stmt_get_result($c))>0)$message='You already have a pending claim for this item.';else{$i=mysqli_prepare($conn,"INSERT INTO claims(item_id,user_id,message,status) VALUES(?,?,?,'pending')");mysqli_stmt_bind_param($i,'iis',$id,$uid,$msg);if(mysqli_stmt_execute($i)){set_flash('success','Claim request sent. Waiting for admin verification.');header('Location: my-claims.php');exit();}$message='Could not send the claim request.';}}}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Claim Item - UniFind</title><link rel="stylesheet" href="css/style.css"></head><body><nav class="navbar"><a class="brand" href="dashboard.php">UniFind</a><div class="nav-actions"><a class="btn btn-small btn-secondary" href="search-items.php">Search Items</a><a class="btn btn-small" href="logout.php">Logout</a></div></nav><main class="form-page"><div class="form-card wide-card"><div class="claim-layout"><div><?php if($item['image']&&is_file(__DIR__.'/uploads/'.$item['image'])):?><img class="claim-image" src="uploads/<?=e($item['image'])?>" alt=""><?php else:?><div class="claim-image placeholder">No Image Available</div><?php endif;?></div><div><span class="status-pill found-pill">FOUND ITEM</span><h1><?=e($item['item_name'])?></h1><div class="detail-list"><span><strong>Category:</strong> <?=e($item['category'])?></span><span><strong>Location:</strong> <?=e($item['location'])?></span><span><strong>Date:</strong> <?=e($item['item_date'])?></span><span><strong>Reported by:</strong> <?=e($item['full_name'])?></span></div><p class="item-description"><?=e($item['description'])?></p></div></div><?php if($message):?><div class="alert alert-error"><?=e($message)?></div><?php endif;?><form method="post" class="form-stack claim-form"><div><label>Ownership Details</label><textarea name="message" required><?=e($_POST['message']??'')?></textarea></div><button class="btn btn-block">Send Claim Request</button></form></div></main><script src="js/ui-effects.js"></script></body></html>